<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import DashboardPageHeader from '@/components/shared/DashboardPageHeader.vue'
import AppButton from '@/components/ui/AppButton.vue'
import { useWorkspaceStore } from '@/stores/workspace'
import { useSiteContentStore } from '@/stores/siteContent'
import { deleteMedia, listMedia, type MediaAsset } from '@/services/mediaLibrary'
import { http } from '@/services/http'
const store = useWorkspaceStore(); const site = useSiteContentStore()
const notice = ref(''); const assets = ref<MediaAsset[]>([]); const busy = ref(false); const pendingAsset = ref(''); const selectedTag = ref(''); const tagName = ref(''); const tagAction = ref('')
const tags = computed(() => [...new Set([...store.papers, ...store.publications, ...store.documents].flatMap(p => p.tags))].sort((a,b) => a.localeCompare(b)))
const usedAssets = computed(() => new Set([...site.content.selectedProjects, ...store.publications].map(p => p.mediaAssetId).filter(Boolean)))
async function refresh() { try { assets.value = await listMedia() } catch { notice.value = 'File storage could not be read. Your content has not been changed.' } }
onMounted(refresh)
async function renameTag() { if (!selectedTag.value || !tagName.value.trim()) { notice.value = 'Choose a tag and enter its new name.'; return }; await store.renameTag(selectedTag.value, tagName.value); notice.value = 'Tag updated across papers, publications and documents.'; selectedTag.value = ''; tagName.value = '' }
async function removeTag() { if (!tagAction.value) return; await store.renameTag(tagAction.value, ''); tagAction.value = ''; selectedTag.value = ''; tagName.value = ''; notice.value = 'Tag removed from all records.' }
async function removeAsset() { if (usedAssets.value.has(pendingAsset.value)) return; try { await deleteMedia(pendingAsset.value); pendingAsset.value = ''; await refresh(); notice.value = 'Unused file deleted.' } catch { notice.value = 'The file could not be deleted. Please retry.' } }
async function backup() {
  busy.value = true
  try {
    const response = await http.get<Blob>('/settings/backup/', { responseType: 'blob' })
    const url = URL.createObjectURL(response.data); const link = document.createElement('a'); link.href = url; link.download = `research-os-backup-${new Date().toISOString().slice(0,10)}.zip`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); notice.value = 'Backup downloaded from the workspace database, including records and original media.'
  } catch { notice.value = 'Backup failed. No stored data was changed.' } finally { busy.value = false }
}
</script>
<template><div><DashboardPageHeader title="Settings" description="Writing defaults, shared tags and server-side media storage."><AppButton :disabled="busy" @click="backup">{{ busy ? 'Preparing backup…' : 'Download full backup' }}</AppButton></DashboardPageHeader><p v-if="notice" role="status" class="feedback">{{ notice }}</p><div class="settings-grid"><section class="record-editor"><h2>Writing defaults</h2><label>New note visibility<select v-model="store.settings.defaultNoteVisibility" @change="store.saveSettings"><option value="private">Private</option><option value="public">Public</option><option value="unlisted">Unlisted</option></select></label><label>New note type<select v-model="store.settings.defaultNoteKind" @change="store.saveSettings"><option>Research Note</option><option>Essay</option><option>Guide</option><option>Reference</option></select></label><p class="muted-copy">Defaults are saved to the workspace database.</p></section><section class="record-editor"><h2>Shared tags</h2><p>Rename or merge tags across recommended papers, publications and documents.</p><label>Existing tag<select v-model="selectedTag" @change="tagName = selectedTag; tagAction = ''"><option value="">Select a tag</option><option v-for="tag in tags" :key="tag">{{ tag }}</option></select></label><label>New name<input v-model="tagName" /></label><div class="editor-actions"><AppButton @click="renameTag">Rename / merge</AppButton><button type="button" class="text-action danger" :disabled="!selectedTag" @click="tagAction = selectedTag">Remove tag everywhere</button></div><div v-if="tagAction" class="inline-confirm"><span>Remove “{{ tagAction }}” from all records?</span><button @click="removeTag">Remove tag</button><button @click="tagAction = ''">Cancel</button></div></section><section class="record-editor settings-wide"><div class="editor-heading"><h2>Media library</h2><button class="text-action" @click="refresh">Refresh</button></div><p>Uploaded originals and interactive packages live on the server. Clear a visual from its record first; only unused files can be deleted here.</p><div v-for="asset in assets" :key="asset.id" class="asset-row"><div><strong>{{ asset.name }}</strong><small>{{ asset.kind }} · {{ (asset.size / 1024 / 1024).toFixed(2) }} MB · {{ usedAssets.has(asset.id) ? 'In use' : 'Unused' }}</small></div><button class="text-action danger" :disabled="usedAssets.has(asset.id)" @click="pendingAsset = asset.id">Delete file</button></div><p v-if="!assets.length" class="empty-hint">No files uploaded yet.</p><div v-if="pendingAsset" class="inline-confirm"><span>Delete this unused file permanently? Export a backup first if you need a copy.</span><AppButton @click="removeAsset">Delete file</AppButton><button @click="pendingAsset = ''">Cancel</button></div></section><section class="record-editor settings-wide"><h2>Current environment</h2><p>Records, authentication and uploaded media are stored by Django. PostgreSQL is used in Docker deployments; SQLite remains available for local development.</p><p>Interactive files execute in an isolated browser frame. Server actions remain explicit and audited; there is no arbitrary shell endpoint.</p><RouterLink to="/dashboard/content">Edit public site content ↗</RouterLink></section></div></div></template>
